from .exceptions import NoUeCapabilities


class UeCapabilities:
    def __init__(self, hex=None, description=None):
        """
        Ue capabilities may be defined either via raw hex value
        or as description of required fields of ueCapabilityInformation.

        Either hex or description parameter should be provided (not both).

        :param hex: ue capabilities encoded as hex string starting from 0x
        :param description: ue capabilities as string describing fields of UeCapabilityInformation message
        :return: None
        """
        self.hex = hex
        self.description = description
        if (hex is None) and (description is None):
            raise NoUeCapabilities(self)

    def __str__(self):
        if (self.hex is None) and (self.description is None):
            return f"{self.__class__.__name__}(hex=None, description=None)"
        info = self.__trim_info(self.hex if self.hex else self.description)
        return f"{self.__class__.__name__}({info})"

    def __repr__(self):
        return self.__str__()

    @staticmethod
    def __trim_info(info, length=23):
        if len(info) > length:
            info = '{:.{width}}...'.format(info, width=length - 3)
        return info
